const amqp = require('amqplib');

async function declareFifoQueue(channel) {
  await channel.assertQueue('order-events', {
    durable: true,
    arguments: {
      'x-queue-type': 'quorum',
      'x-single-active-consumer': true
    }
  });

  channel.prefetch(1);
  const { consumerTag } = await channel.consume('order-events', (msg) => {
    if (msg !== null) {
      console.log('Received:', msg.content.toString());
      channel.ack(msg);
    }
  }, { noAck: false });

  console.log('Consumer tag:', consumerTag);
}

using Amazon.SQS;
using Amazon.SQS.Model;

public class SqsFifoProducer
{
    private readonly IAmazonSQS _sqs;
    private readonly string _queueUrl;

    public SqsFifoProducer(IAmazonSQS sqs, string queueUrl)
    {
        _sqs = sqs;
        _queueUrl = queueUrl;
    }

    public async Task SendAsync(string groupId, string body, string messageDeduplicationId)
    {
        var request = new SendMessageRequest
        {
            QueueUrl = _queueUrl,
            MessageBody = body,
            MessageGroupId = groupId,
            MessageDeduplicationId = messageDeduplicationId
        };

        var response = await _sqs.SendMessageAsync(request);
        Console.WriteLine($"Sent {response.MessageId} to group {groupId}");
    }
}
